const { withAppBuildGradle } = require("@expo/config-plugins");

const MARKER = "// --- with-newpipe-desugaring (generated; do not hand-edit) ---";

/**
 * NewPipe Extractor uses java.time / java.nio APIs that need core-library
 * desugaring on minSdk < 33. app/build.gradle is generated by prebuild, so this
 * plugin appends the blocks on every prebuild. Idempotent via MARKER.
 */
module.exports = function withNewpipeDesugaring(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.contents.includes(MARKER)) return cfg;
    cfg.modResults.contents += `
${MARKER}
android {
    compileOptions {
        isCoreLibraryDesugaringEnabled = true
    }
}
dependencies {
    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs_nio:2.1.5")
}
`;
    return cfg;
  });
};